import sys
import time

def main():
    if len(sys.argv) < 2:
        print("Usage: python3 open_handles.py <number_of_handles>")
        sys.exit(1)

    num_handles = int(sys.argv[1])
    handles = []

    print(f"Attempting to open {num_handles} file handles to /dev/null...")
    try:
        for _ in range(num_handles):
            # Opening /dev/null is cheap and safe for exhausting file descriptors
            f = open('/dev/null', 'r')
            handles.append(f)
    except Exception as e:
        print(f"Stopped early at {len(handles)} handles due to error: {e}")

    print(f"Successfully opened {len(handles)} handles. Sleeping indefinitely to hold them open...")

    # Sleep to keep the process and its file handles alive
    try:
        while True:
            time.sleep(3600)
    except KeyboardInterrupt:
        print("\nExiting and releasing handles.")

if __name__ == "__main__":
    main()
